func a(s struct{ mount string }) { log.Printf("mount %s", s.mount) }
`,
			want: []string{"x.go:3: s.mount"},
		},
		{
			name: "an error printed with %v",
			src: `package p
import "log"
func a(err error) { log.Printf("failed: %v", err) }
